using System.Data; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class DashboardPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Dashboard", "View"); var summary = DbHelper.ExecuteDataTable(@"SELECT (SELECT COUNT(1) FROM Customers) AS TotalCustomers,(SELECT COUNT(1) FROM Customers WHERE Status = 'Active') AS ActiveCustomers,(SELECT COUNT(1) FROM Customers WHERE Status = 'Pending') AS PendingRegistrations,(SELECT COUNT(1) FROM Collections WHERE CAST(CollectionDate AS date) = CAST(GETDATE() AS date)) AS TodaysCollections,(SELECT COUNT(1) FROM CollectionRequests WHERE Status = 'Pending') AS PendingCollectionRequests,(SELECT COUNT(1) FROM Collections WHERE Status = 'Completed') AS CompletedCollections,(SELECT COUNT(1) FROM Invoices WHERE Status IN ('Pending','Partial','Overdue')) AS PendingPayments,(SELECT ISNULL(SUM(AmountPaid),0) FROM Payments WHERE CAST(PaymentDate AS date) = CAST(GETDATE() AS date)) AS TodaysRevenue,(SELECT COUNT(1) FROM Complaints WHERE Status IN ('Open','Assigned','In Progress')) AS OpenComplaints,(SELECT COUNT(1) FROM ShopOrders) AS ShopOrders,(SELECT COUNT(1) FROM Users WHERE IsActive = 1) AS ActiveUsers,(SELECT COUNT(1) FROM UserSessions WHERE IsActive = 1 AND IsRevoked = 0) AS ActiveSessions", CommandType.Text); return new { success = true, data = DbHelper.ToDictionaryList(summary) }; } } }
